#[test]
fn duplicate_permission_and_awaiting_user_responses_are_applied_once() {
    let (mut host, project, storage) = test_host("duplicate-decisions");
    let session = host.create_session("Remote").expect("session");
    let version = host.session(&session).expect("session").proposal.version;
    let run = host.start_run_authorized(&session, version, "test").expect("run");
    assert_eq!(
        host.check_permission(&run, AgentCapability::FrameCapture)
            .expect("permission request"),
        crate::agent_host::PermissionCheck::RequiresApproval
    );

    let mut cache = MutationCache::default();
    let permission = RemoteOperation::Permission {
        run_id: run.clone(),
        request_id: "permission-one".into(),
        capability: AgentCapability::FrameCapture,
        scope: RemotePermissionScope::Once,
    };
    for _ in 0..2 {
        let _ = cache.execute(&permission, || {
            host.resolve_permission(
                &run,
                AgentCapability::FrameCapture,
                crate::agent_host::ApprovalScope::Once,
            )
            .expect("permission resolved");
            RemoteAiStudioResponse::json(json!({"ok": true}))
        });
    }
    assert_eq!(
        host.run(&run)
            .expect("run")
            .events
            .iter()
            .filter(|event| event.kind == AgentEventKind::PermissionResolved)
            .count(),
        1
    );

    host.transition_run(&run, AgentRunState::AwaitingUser, "Need input")
        .expect("awaiting");
    let awaiting = RemoteOperation::AwaitingUser {
        run_id: run.clone(),
        request_id: "await-one".into(),
        text: "continue".into(),
    };
    for _ in 0..2 {
        let _ = cache.execute(&awaiting, || {
            host.append_message(&session, crate::agent_host::ConversationRole::User, "continue")
                .expect("message");
            host.transition_run(
                &run,
                AgentRunState::Executing,
                "User response received; execution may continue.",
            )
            .expect("resume");
            RemoteAiStudioResponse::json(json!({"ok": true}))
        });
    }
    assert_eq!(host.run(&run).expect("run").state, AgentRunState::Executing);
    assert_eq!(
        host.session(&session)
            .expect("session")
            .messages
            .iter()
            .filter(|message| message.text == "continue")
            .count(),
        1
    );
    let _ = fs::remove_dir_all(project);
    let _ = fs::remove_dir_all(storage);
}
